<script setup>
import { Head, Link } from '@inertiajs/vue3';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import { actionLabel, fieldLabel, formatTime } from '../../../utils/activityLabels';
defineProps({ entry: Object, changes: Array, versionUrl: String });
const value = (data) => data === null || data === undefined ? '—' : typeof data === 'object' ? JSON.stringify(data, null, 2) : typeof data === 'boolean' ? data ? 'Ya' : 'Tidak' : String(data);
</script>
<template><Head title="Detail Aktivitas" /><AdminLayout><Link href="/admin/system/activity" class="text-xs text-interactive">Kembali ke riwayat</Link><h1 class="mt-5 text-2xl font-semibold">{{ actionLabel(entry.action) }}</h1><p class="mt-2 text-sm text-muted">{{ entry.actor || 'Sistem' }} · {{ formatTime(entry.created_at) }}</p><p v-if="entry.target" class="mt-2 text-sm">Sasaran: {{ entry.target }}</p><p class="mt-3 text-sm">{{ entry.summary }}</p><Link v-if="versionUrl" :href="versionUrl" class="admin-secondary mt-5">Lihat versi sumber</Link><section class="learning-panel mt-6"><div class="overflow-x-auto"><table class="w-full min-w-[600px] table-fixed text-left text-sm"><thead class="bg-page text-xs text-muted"><tr><th class="w-1/3 p-4">Bagian yang berubah</th><th class="p-4">Sebelum</th><th class="p-4">Sesudah</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="(change, i) in changes" :key="i"><th scope="row" class="break-words p-4 align-top text-xs font-medium">{{ fieldLabel(change.field) }}</th><td class="p-4 align-top"><pre class="whitespace-pre-wrap break-words text-xs leading-6">{{ value(change.before) }}</pre></td><td class="p-4 align-top"><pre class="whitespace-pre-wrap break-words text-xs leading-6">{{ value(change.after) }}</pre></td></tr><tr v-if="!changes.length"><td colspan="3" class="p-8 text-center text-muted">Aktivitas ini tidak mengubah data.</td></tr></tbody></table></div></section></AdminLayout></template>
